package ir.mahdi.app;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 int green=Color.rgb(16,42,37),gold=Color.rgb(181,138,69);
 String[] titles={"دعای فرج","صلوات","ذکر استغفار"};
 String[] ar={"اللَّهُمَّ كُنْ لِوَلِيِّكَ الْحُجَّةِ بْنِ الْحَسَنِ، صَلَوَاتُكَ عَلَيْهِ وَعَلَى آبَائِهِ، فِي هذِهِ السَّاعَةِ وَفِي كُلِّ سَاعَةٍ، وَلِيّاً وَحَافِظاً، وَقَائِداً وَنَاصِراً، وَدَلِيلاً وَعَيْناً، حَتَّى تُسْكِنَهُ أَرْضَكَ طَوْعاً، وَتُمَتِّعَهُ فِيهَا طَوِيلاً.","اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ","أَسْتَغْفِرُ اللَّهَ رَبِّي وَأَتُوبُ إِلَيْهِ"};
 String[] fa={"خدایا، برای ولیّ خود حجت بن الحسن، در این ساعت و در همه ساعت‌ها سرپرست و نگهبان و پیشوا و یاور و راهنما و دیده‌بان باش، تا او را در زمین خود با رغبت جای دهی و زمانی طولانی بهره‌مند سازی.","خدایا بر محمد و خاندان محمد درود فرست.","از خداوند، پروردگارم، آمرزش می‌خواهم و به سوی او بازمی‌گردم."};
 LinearLayout root; ScrollView sc; Handler h=new Handler(); boolean moving=false;
 GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(26);return d;}
 TextView txt(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setTextDirection(View.TEXT_DIRECTION_RTL);t.setPadding(18,18,18,18);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 TextView btn(String s){TextView t=txt(s,16,Color.WHITE,true);t.setBackground(shape(green));return t;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(green);getWindow().setNavigationBarColor(green);home();}
 void home(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff6f3eb);TextView head=txt("گنجینهٔ ادعیه و مناجات",24,Color.WHITE,true);head.setBackgroundColor(green);root.addView(head);root.addView(txt("ذکر آرامش دل و یاد خدا",15,green,false));for(int i=0;i<titles.length;i++){final int n=i;TextView item=txt(titles[i]+"   ←",20,green,true);item.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);item.setBackground(shape(Color.WHITE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(16,9,16,9);root.addView(item,p);item.setOnClickListener(v->detail(n));}setContentView(root);}
 void detail(int n){moving=false;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff6f3eb);TextView back=btn("← بازگشت");root.addView(back);back.setOnClickListener(v->home());root.addView(txt(titles[n],23,green,true));sc=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(1);TextView a=txt(ar[n],28,green,true);a.setLineSpacing(12,1.1f);a.setBackground(shape(Color.WHITE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(14,12,14,12);body.addView(a,p);TextView f=txt(fa[n],18,Color.DKGRAY,false);f.setBackground(shape(0xffeee8da));body.addView(f,p);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));TextView auto=btn("شروع حرکت خودکار");root.addView(auto);auto.setOnClickListener(v->{moving=!moving;auto.setText(moving?"توقف":"شروع حرکت خودکار");scroll();});root.addView(txt("فایل صوتی هنوز به این نسخه اضافه نشده است.",13,Color.GRAY,false));setContentView(root);}
 void scroll(){h.postDelayed(new Runnable(){public void run(){if(!moving)return;if(sc.getScrollY()+sc.getHeight()>=sc.getChildAt(0).getHeight()){moving=false;return;}sc.smoothScrollBy(0,2);scroll();}},80);}
}
